changeSet.sql:
ALTER TABLE product DROP CONSTRAINT IF EXISTS chk_product_wildberries_url_canonical;
ALTER TABLE product
    ADD CONSTRAINT chk_product_wildberries_url_canonical
    CHECK (
        wildberries_url IS NULL
        OR wildberries_url = 'https://global.wildberries.ru/seller/4398117'
        OR wildberries_url ~ '^https://global\.wildberries\.ru/catalog/[1-9][0-9]*/detail\.aspx$'
    );

rollback.sql:
ALTER TABLE product DROP CONSTRAINT IF EXISTS chk_product_wildberries_url_canonical;
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM product
        WHERE wildberries_url IS NOT NULL
          AND wildberries_url != 'https://global.wildberries.ru/seller/4398117'
    ) THEN
        RAISE EXCEPTION 'Cannot roll back Wildberries product source links without losing product-specific URLs';
    END IF;
END $$;
ALTER TABLE product
    ADD CONSTRAINT chk_product_wildberries_url_canonical
    CHECK (
        wildberries_url IS NULL
        OR wildberries_url = 'https://global.wildberries.ru/seller/4398117'
    );
